<!-- This file is generated by AI. -->
<!--
  文件行 / 选项卡右侧的徽标: git 更改类型 + 诊断条数。

  单独一个组件是因为同一套徽标要在**三处**出现 (场景浏览、资源浏览、选项卡栏), 各自的父级结构
  不同 —— 放在一处定义, 三处的样子与语义才不会各自漂。数据默认直接读 store: 徽标是"这个文件现在
  怎么样"的**派生视图**, 让每个调用点自己去查会出现三份口径。

  ⚠️ 不带 `<style>` 块 —— 类名来自全局 `styles.css`。
-->
<script lang="ts">
  import type { GitStatusLetter } from '../commands/git';
  import { SEVERITY_LABELS } from '../diagnostics/model';
  import { absToRel } from '../git/util';
  import { appStore } from '../state/store.svelte';

  let {
    /** 文件的绝对路径 (与 store 里的 `documents[].path` / 诊断键一致) */
    path,
    /**
     * 项目内相对路径 (正斜杠): git 状态是按它索引的。
     *
     * 省略时由 `path` + 当前项目路径自己算 —— 让三个调用点各自去算正是文件头警告过的"三份口径"
     * (选项卡栏只拿得到绝对路径)。
     */
    rel,
    /**
     * **由父级解析好的徽标值** (可选)。给了就不再读 store。
     *
     * 为什么要有这条路径: 列表里一行一个 `FileBadges`, 每行都自己读 `appStore.gitStatus` /
     * `appStore.diagnostics` 就是**每行一个 store 订阅**, 而诊断按项目整份重推、git 状态在进列表时
     * 刷新, 于是每次写入都会唤醒全部行 (每行的 git 查询还是 O(状态条数) 的线性 `find`), 文件上千时
     * 主线程被卡住。
     *
     * 列表类调用点 (`ResourceBrowser` / `SceneBrowser`) 因此用 `buildGitLetterIndex` /
     * `buildDiagnosticIndex` **建一次表**, 每行只做一次 O(1) 查表: 订阅从 N 个收敛成 1 个。
     * 三个值都为 `undefined` 时 (`TabStrip` 那种少量调用点) 仍走 store 路径。
     */
    letter,
    errors,
    warnings,
  }: {
    path: string;
    rel?: string;
    letter?: GitStatusLetter | null;
    errors?: number;
    warnings?: number;
  } = $props();

  /** 父级是否已经把值解析好了 (三个可选 prop 里给了任意一个就算)。 */
  const resolved = $derived(letter !== undefined || errors !== undefined || warnings !== undefined);

  /** git 状态用的相对路径: 调用方给了就用它, 没给就从项目路径推。 */
  const relative = $derived.by(() => {
    if (rel) return rel;
    if (resolved) return '';
    const projectPath = appStore.projectPath;
    return projectPath ? absToRel(projectPath, path) : '';
  });

  /**
   * 这个文件的 git 更改类型。
   *
   * 已暂存与未暂存可能同时存在同一个路径, 因此**优先显示已暂存** —— 那一步是用户刚确认过的
   * 动作, 比"又改了"更值得提示。索引表的构建口径与此一致 (见 `buildGitLetterIndex`)。
   */
  const gitLetter = $derived.by<GitStatusLetter | null>(() => {
    if (resolved) return letter ?? null;
    const status = appStore.gitStatus;
    if (!status?.initialized || !relative) return null;
    const normalized = relative.replace(/\\/g, '/').replace(/^\/+/, '').toLowerCase();
    const find = (files: { path: string; status: GitStatusLetter }[] | undefined) =>
      files?.find((file) => file.path.replace(/\\/g, '/').replace(/^\/+/, '').toLowerCase() === normalized);
    return find(status.staged)?.status ?? find(status.unstaged)?.status ?? null;
  });

  /** 这个文件的诊断条数, 按级别分。 */
  const diagnostics = $derived(resolved ? [] : (appStore.diagnostics[path] ?? []));
  const errorCount = $derived(resolved ? (errors ?? 0) : diagnostics.filter((item) => item.severity === 1).length);
  const warnCount = $derived(resolved ? (warnings ?? 0) : diagnostics.filter((item) => item.severity === 2).length);

  const hasAny = $derived(gitLetter !== null || errorCount > 0 || warnCount > 0);
</script>

{#if hasAny}
  <span class="file-badges">
    {#if gitLetter}
      <!--
        类名是 `git-<字母>`, 颜色由 styles.css 里 `.git-M` / `.git-A` 等一组规则给。
        用模板拼而不是查表: 字母集合就是 git 的状态字母, 加一张映射表只会多一处要同步的地方。
      -->
      <span class="git-file-status git-{gitLetter}" title="版本控制状态：{gitLetter}">{gitLetter}</span>
    {/if}
    {#if errorCount > 0}
      <span class="diag-badge diag-error" title="{SEVERITY_LABELS[1]} {errorCount} 条">{errorCount}</span>
    {/if}
    {#if warnCount > 0}
      <span class="diag-badge diag-warn" title="{SEVERITY_LABELS[2]} {warnCount} 条">{warnCount}</span>
    {/if}
  </span>
{/if}
